import psutil

def monitor_connections(host: str, interval_s: int) -> list[dict]:
    logs = []
    end_time = time.time() + interval_s

    while time.time() < end_time:
        try:
            connections = psutil.net_connections(kind='inet')
            for conn in connections:
                if conn.status == psutil.CONN_ESTABLISHED and conn.laddr:
                    if conn.laddr.ip == host or host == '0.0.0.0':
                        logs.append({
                            'timestamp': time.time(),
                            'source_ip': conn.raddr.ip if conn.raddr else None,
                            'source_port': conn.raddr.port if conn.raddr else None
                        })
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            pass
        time.sleep(1)

    return logs
