import pyshark
from collections import Counter
import math

def _shannon_entropy(data: str) -> float:
    if not data: return 0.0
    freq = Counter(data)
    return -sum((c/len(data)) * math.log2(c/len(data)) for c in freq.values())

def analyze_dns_traffic(pcap_file: str) -> dict:
    suspicious = {"dga": [], "tunneling": [], "exfiltration": []}
    query_lengths = Counter()

    capture = pyshark.FileCapture(pcap_file, display_filter='dns.flags.response == 0')

    for pkt in capture:
        try:
            query = pkt.dns.qry_name.lower()
            domain = '.'.join(query.split('.')[-2:])
            labels = query.split('.')

            # DGA: Hög entropi eller långt slumpmässigt subdomännamn
            if len(labels[-2]) > 15 and _shannon_entropy(labels[-2]) > 3.5:
                if domain not in suspicious["dga"]:
                    suspicious["dga"].append(domain)

            # Tunneling: Mycket långa frågor eller många TXT/NULL/TXT-förfrågningar
            if len(query) > 100:
                if query not in suspicious["tunneling"]:
                    suspicious["tunneling"].append(query)

            # Exfiltration: Ovanligt många unika subdomäner för samma domän
            query_lengths[domain] += 1
            if query_lengths[domain] > 50:
                if domain not in suspicious["exfiltration"]:
                    suspicious["exfiltration"].append(domain)
        except AttributeError:
            continue

    capture.close()
    return suspicious
```

